import { supabase } from './supabase-client.js';
import './workflow-studio.js?v=20260911-wf3';

if(!document.querySelector('link[data-wr22-css]')){const l=document.createElement('link');l.rel='stylesheet';l.href='./wr-canonical-v22.css?v=20260912-v22';l.dataset.wr22Css='1';document.head.appendChild(l)}
const main=document.getElementById('main');
let S=null,wrId=null,mode='guided',tab='overview',manualStep=null,cargoQuery='',docGroup='category',pendingDocMeta=null;
const selectedCargo=new Set(),selectedDocs=new Set();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v?new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(v)):'—';
const tm=v=>v?new Intl.DateTimeFormat(undefined,{hour:'numeric',minute:'2-digit'}).format(new Date(v)):'—';
const scanIcon=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M8 3H5a2 2 0 0 0-2 2v3M16 3h3a2 2 0 0 1 2 2v3M3 16v3a2 2 0 0 0 2 2h3M21 16v3a2 2 0 0 1-2 2h-3"/><rect x="8" y="8" width="8" height="8" rx="2"/></svg>`;
const docIcon=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M6 3h8l4 4v14H6z"/><path d="M14 3v5h5M9 13h6M9 17h6"/></svg>`;
const cameraIcon=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 7h3l2-2h6l2 2h3v12H4z"/><circle cx="12" cy="13" r="4"/></svg>`;
const mailIcon=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 5h18v14H3z"/><path d="m3 7 9 6 9-6"/></svg>`;
const FALLBACK=[['check_in','Check in',20,true],['verify_driver','Verify driver',30,true],['start_unload','Start unload',40,true],['finish_unload','Unload & tally',50,true],['release_driver','Release driver',60,true],['parties','Parties',70,true],['receive_cargo','Receive cargo',80,true],['documents','Documents',90,false],['compliance','Compliance',100,false],['putaway','Put away',110,true],['complete','Review & complete',120,true],['notify_customer','Notify customer',130,false]].map(([key,label,order,required])=>({key,label,order,required,enabled:true}));
const BASE_TYPES=[['PALLET','PLT'],['SKID','SKD'],['CRATE','CRT'],['CARTON','CTN'],['BOX','BOX'],['DRUM','DRM'],['BAG','BAG'],['PIECE','EA']];
function toast(t){let e=document.querySelector('.wr22-toast');if(!e){e=document.createElement('div');e.className='wr22-toast';document.body.appendChild(e)}e.textContent=t;e.classList.add('show');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('show'),1600)}
async function uid(){const{data}=await supabase.auth.getUser();return data?.user?.id||null}
const ent=id=>S.entities.find(x=>x.id===id),party=r=>S.parties.find(x=>String(x.role||'').toLowerCase()===r),roots=()=>S.cargo.filter(x=>!x.parent_id),children=id=>S.cargo.filter(x=>x.parent_id===id);
const customerName=()=>ent(S.job?.customer_id)?.name||'Unidentified customer';
const packageTypes=()=>[...new Map([...BASE_TYPES,...(S.options||[]).filter(x=>x.option_group==='PACKAGE_TYPE'&&x.active).map(x=>[x.code,x.uom||x.code])].map(x=>[x[0],x])).values()];
const steps=()=>[...(S.workflow?.steps||FALLBACK)].filter(x=>x.enabled!==false).sort((a,b)=>(a.order||0)-(b.order||0));
const skipped=k=>S.events.some(e=>e.event_type==='STEP_SKIPPED'&&e.event_data?.step_key===k);
function done(s){const v=S.visit||{},r=roots().filter(x=>!x.metadata?.editor_draft);switch(s.key){case'check_in':return!!v.time_in;case'verify_driver':return!!v.driver_id_verified;case'start_unload':return!!v.operation_started_at;case'finish_unload':return!!v.operation_completed_at;case'release_driver':return!!v.time_out;case'parties':return(!!S.job?.customer_id&&!!party('shipper')&&!!party('consignee'))||skipped('parties');case'receive_cargo':return r.length>0&&r.every(x=>x.processing_status==='processed');case'documents':return S.docs.length>0||skipped('documents');case'compliance':return S.controls.length===0||S.controls.every(x=>x.verified||['complete','cleared','released'].includes(String(x.status||'').toLowerCase()))||skipped('compliance');case'putaway':return(r.length>0&&r.every(x=>x.current_location_id||x.warehouse_location_id))||skipped('putaway');case'complete':return!!S.wr.completed_at;case'notify_customer':return S.events.some(e=>e.event_type==='CUSTOMER_NOTIFIED')||skipped('notify_customer');default:return S.events.some(e=>e.event_type==='STEP_COMPLETED'&&e.event_data?.step_key===s.key)||skipped(s.key)}}
const current=()=>steps().find(x=>x.key===manualStep)||steps().find(x=>!done(x))||steps().at(-1);
function missing(){const m=[];if(!S.job?.customer_id)m.push('Customer');if(!party('shipper'))m.push('Shipper');if(!party('consignee'))m.push('Consignee');if(!roots().filter(x=>!x.metadata?.editor_draft).length)m.push('Cargo');if(S.visit?.time_in&&!S.visit?.time_out)m.push('Driver on site');if(roots().filter(x=>!x.metadata?.editor_draft).some(x=>!(x.current_location_id||x.warehouse_location_id)))m.push('Put-away');if(S.flags.length)m.push(`${S.flags.length} exception${S.flags.length===1?'':'s'}`);if(S.controls.some(x=>!x.verified&&!['complete','cleared','released'].includes(String(x.status||'').toLowerCase())))m.push('Compliance');return m}
function summary(){const r=roots().filter(x=>!x.metadata?.editor_draft);return{expected:S.visit?.unload_expected_qty,unloaded:S.visit?.unload_actual_qty,processed:r.filter(x=>x.processing_status==='processed').reduce((a,x)=>a+Number(x.quantity||0),0),putaway:r.filter(x=>x.current_location_id||x.warehouse_location_id).reduce((a,x)=>a+Number(x.quantity||0),0),exceptions:S.flags.length,missing:missing().length}}
function completion(){const a=steps();return a.length?Math.round(a.filter(done).length/a.length*100):0}
async function addEvent(type,data={}){await supabase.from('workflow_events').insert({organization_id:S.wr.organization_id,job_id:S.wr.job_id,warehouse_receipt_id:wrId,event_type:type,event_data:data,actor_id:await uid()})}
async function load(id){const{data:wr,error}=await supabase.from('warehouse_receipts').select('*').eq('id',id).single();if(error)throw error;const q=[supabase.from('jobs').select('*').eq('id',wr.job_id).maybeSingle(),supabase.from('warehouse_visits').select('*').eq('warehouse_receipt_id',id).eq('direction','inbound').order('created_at',{ascending:false}).limit(1),supabase.from('cargo_units').select('*').eq('job_id',wr.job_id).order('created_at'),supabase.from('warehouse_receipt_parties').select('*').eq('warehouse_receipt_id',id),supabase.from('entities').select('*').eq('organization_id',wr.organization_id).order('name').limit(2500),supabase.from('documents').select('*').eq('warehouse_receipt_id',id).eq('is_current',true).order('created_at',{ascending:false}),supabase.from('operational_flags').select('*').eq('warehouse_receipt_id',id).eq('active',true).order('created_at',{ascending:false}),supabase.from('receiving_controls').select('*').eq('warehouse_receipt_id',id).order('created_at',{ascending:false}),supabase.from('workflow_definitions').select('*').eq('organization_id',wr.organization_id).eq('transaction_type','WAREHOUSE_RECEIPT').eq('is_active',true).order('version',{ascending:false}).limit(1),supabase.from('workflow_events').select('*').eq('warehouse_receipt_id',id).order('created_at'),supabase.from('warehouse_locations').select('*').eq('organization_id',wr.organization_id).eq('active',true).order('code'),supabase.from('organization_unit_profiles').select('*').eq('organization_id',wr.organization_id).eq('is_default',true).maybeSingle(),supabase.from('organization_reference_options').select('*').eq('organization_id',wr.organization_id).eq('active',true).order('option_group').order('sort_order'),supabase.from('inventory_items').select('id,owner_entity_id,part_number,sku,description,base_uom,lot_tracking,serial_tracking,metadata').eq('organization_id',wr.organization_id).limit(2500)];const[job,visit,cargo,parties,entities,docs,flags,controls,wf,events,locs,units,opts,items]=await Promise.all(q);const ids=(entities.data||[]).map(x=>x.id);let addresses=[],contacts=[];if(ids.length){const[a,c]=await Promise.all([supabase.from('entity_addresses').select('*').in('entity_id',ids).eq('active',true),supabase.from('entity_contacts').select('*').in('entity_id',ids).eq('active',true)]);addresses=a.data||[];contacts=c.data||[]}S={wr,job:job.data||{},visit:visit.data?.[0]||null,cargo:cargo.data||[],parties:parties.data||[],entities:entities.data||[],docs:docs.data||[],flags:flags.data||[],controls:controls.data||[],workflow:wf.data?.[0]||null,events:events.data||[],locations:locs.data||[],units:units.data||{weight_unit:'LB',dimension_unit:'IN'},options:opts.data||[],items:items.data||[],addresses,contacts}}
async function rerender(reset=false){await load(wrId);if(reset)manualStep=null;render()}
function timeline(){const v=S.visit||{};return `<div class="wr22-timeline">${[['Checked in',v.time_in],['ID verified',v.driver_id_verified_at],['Unload started',v.operation_started_at],['Unload finished',v.operation_completed_at],['Released',v.time_out]].map(([l,t])=>`<div class="wr22-event ${t?'done':''}"><small>${l}</small><b>${t?'✓ '+tm(t):'Pending'}</b></div>`).join('')}</div>`}
function commandbar(){return `<div class="wr22-command"><button data-out="pdf">${docIcon}<span>WR PDF</span></button><button data-out="4x6">4×6</button><button data-out="2x1">2×1</button><button data-doc-scan>${scanIcon}<span>Scan document</span></button><button data-doc-upload>${docIcon}<span>Upload</span></button><button data-share>${mailIcon}<span>Share</span></button></div>`}
function head(){const s=summary(),pct=completion(),reconcile=s.unloaded&&s.processed>s.unloaded?`<div class="wr22-warning"><span>Reconciliation needed · ${s.processed} processed vs ${s.unloaded} unloaded (+${s.processed-s.unloaded}).</span><button data-overage>Record overage</button></div>`:'';return `<header class="wr22-head"><div class="wr22-headrow"><div><div class="wr22-k">Warehouse receipt</div><div class="wr19-num wr22-num">${esc(S.wr.receipt_number)}</div><div class="wr22-sub">${esc(customerName())} · Created ${fmt(S.wr.created_at)}${S.wr.received_at?` · Received ${fmt(S.wr.received_at)}`:''}</div></div><span class="wr22-status">${esc(S.wr.status)}</span></div><div class="wr22-mode"><button data-mode="guided" class="${mode==='guided'?'active':''}">Guided</button><button data-mode="record" class="${mode==='record'?'active':''}">Record</button></div>${commandbar()}<div class="wr22-summary"><div class="wr22-stat"><small>Expected</small><b>${s.expected??'—'} ${S.visit?.unload_uom||''}</b></div><div class="wr22-stat"><small>Unloaded</small><b>${s.unloaded??'—'} ${S.visit?.unload_uom||''}</b></div><div class="wr22-stat"><small>Processed</small><b>${s.processed}</b></div><div class="wr22-stat"><small>Put away</small><b>${s.putaway}</b></div><div class="wr22-stat"><small>Exceptions</small><b>${s.exceptions}</b></div><div class="wr22-stat"><small>Missing</small><b>${s.missing}</b></div></div><div class="wr22-meter"><span style="width:${pct}%"></span></div>${reconcile}</header>`}
function progress(){const c=current();return `<div class="wr22-progress">${steps().map(x=>`<button data-step="${x.key}" class="${done(x)?'done':''} ${x.key===c?.key?'now':''}">${done(x)?'✓ ':''}${esc(x.label)}${x.required===false?' · optional':''}</button>`).join('')}</div>`}
const copy=k=>({check_in:'Capture only what establishes the dock visit.',verify_driver:'Capture the ID directly to this WR and record the verification.',start_unload:'Start physical unloading when custody transfer begins.',finish_unload:'Record the physical tally. Detailed receiving can continue after release.',release_driver:'Capture signature and close the dock visit.',parties:'Confirm Customer, Shipper and Consignee, or continue with identity pending.',receive_cargo:'Build the physical cargo hierarchy. Cargo drafts autosave.',documents:'Capture and organize documents by type and cargo.',compliance:'Use structured DG, in-bond / 7512 and FTZ controls only when applicable.',putaway:'Assign or scan locations. You can skip and return later.',complete:'Review unresolved requirements before completion.',notify_customer:'Share the WR or record notification.'}[k]||'Complete this step.');
function smartField(id,label,value='',role=''){return `<label class="wr22-field" data-smart-wrap><span>${esc(label)}</span><input id="${id}" data-smart="${role}" value="${esc(value)}" autocomplete="off" placeholder="Search, type once, or create new"><div class="wr22-smartmenu" hidden></div><div class="wr22-preview" data-preview hidden></div></label>`}
function partyCard(role){const p=role==='customer'?ent(S.job?.customer_id):ent(party(role)?.entity_id),name=role==='customer'?customerName():(party(role)?.display_name||p?.name||'Not selected');if(!p)return `<div class="wr22-party"><small>${role}</small><h4>${esc(name)}</h4><div class="addr">${name==='Not selected'||name==='Unidentified customer'?'Pending':'Typed for this WR only'}</div></div>`;const a=S.addresses.find(x=>x.entity_id===p.id&&x.is_primary)||S.addresses.find(x=>x.entity_id===p.id),c=S.contacts.find(x=>x.entity_id===p.id&&x.is_primary)||S.contacts.find(x=>x.entity_id===p.id);return `<div class="wr22-party"><small>${role}</small><h4>${esc(p.name)}</h4><div class="addr">${esc([a?.line1,a?.line2,[a?.city,a?.state_region,a?.postal_code].filter(Boolean).join(' '),a?.country_code].filter(Boolean).join(' · ')||'No saved address')}</div><div class="contact">${esc([c?.name,c?.phone,c?.email].filter(Boolean).join(' · ')||'No primary contact')}</div></div>`}
function guided(){const s=current(),i=steps().findIndex(x=>x.key===s.key);return `<section class="wr22-guide wr22-panel">${progress()}<div class="wr22-now">RIGHT NOW · ${i+1} OF ${steps().length}</div><h1 class="wr22-title">${esc(s.label)}</h1><div class="wr22-copy">${esc(s.description||copy(s.key))}</div>${timeline()}${guidedTask(s)}</section>`}
function guidedTask(s){const v=S.visit||{};switch(s.key){case'check_in':return `<div class="wr22-task"><h3>Who just arrived?</h3><div class="wr22-fields">${smartField('g-carrier','Carrier',v.carrier_name_snapshot||'','carrier')}<label class="wr22-field"><span>Driver</span><input id="g-driver" value="${esc(v.driver_name||'')}" placeholder="Driver name"></label><label class="wr22-field"><span>Reference</span><input id="g-ref" value="${esc(v.bol_number||v.pro_number||v.tracking_number||'')}" placeholder="BOL / PRO / tracking"></label><label class="wr22-field"><span>Door</span><input id="g-door" value="${esc(v.door||'')}" placeholder="Optional"></label></div><div class="wr22-actions"><button class="primary" data-checkin>Check in</button><button class="wr22-icon" data-scan-ref>${scanIcon} Scan reference</button></div></div>`;case'verify_driver':return `<div class="wr22-task"><h3>Verify identity</h3><p>The ID scan is attached directly to this open WR / dock visit.</p><div class="wr22-actions"><button class="wr22-icon" data-driver-id>${scanIcon} Scan / capture ID</button></div><label style="display:flex;gap:9px;align-items:flex-start;margin-top:16px;line-height:1.45"><input id="g-verify" type="checkbox" style="width:20px;height:20px;flex:none"><span>I verified a government-issued photo ID and confirmed it matches the driver presenting the freight.</span></label><div class="wr22-actions"><button class="primary" data-verify>Confirm verification</button></div></div>`;case'start_unload':return `<div class="wr22-task"><h3>Ready to unload</h3><div class="wr22-actions"><button class="primary" data-start-unload>Start unloading</button></div></div>`;case'finish_unload':return `<div class="wr22-task"><h3>Unload & tally</h3><div class="wr22-fields"><label class="wr22-field"><span>Expected</span><input id="g-exp" type="number" value="${esc(v.unload_expected_qty??'')}"></label><label class="wr22-field"><span>Actual unloaded</span><input id="g-act" type="number" value="${esc(v.unload_actual_qty??'')}"></label><label class="wr22-field"><span>UOM</span><input id="g-uom" value="${esc(v.unload_uom||'PLT')}"></label></div><div class="wr22-actions"><button class="primary" data-finish-unload>Finish unloading</button></div></div>`;case'release_driver':return `<div class="wr22-task"><h3>Release driver</h3><p>Signature + time-out closes the dock visit. Warehouse processing continues independently.</p><div class="wr22-actions"><button class="primary" data-release>Sign & release driver</button></div></div>`;case'parties':return `<div class="wr22-task"><h3>Parties</h3><div class="wr22-fields">${smartField('g-customer','Customer',customerName()==='Unidentified customer'?'':customerName(),'customer')}${smartField('g-shipper','Shipper',party('shipper')?.display_name||'','shipper')}${smartField('g-consignee','Consignee',party('consignee')?.display_name||'','consignee')}</div><div class="wr22-actions"><button class="primary" data-save-parties>Save & continue</button><button class="quiet" data-pending-parties>Continue · identity pending →</button></div></div>`;case'receive_cargo':return `<div class="wr22-task">${cargoView()}</div>`;case'documents':return `<div class="wr22-task">${documentsView()}${s.required===false?'<div class="wr22-actions"><button class="quiet" data-skip="documents">Skip optional step →</button></div>':''}</div>`;case'compliance':return `<div class="wr22-task">${complianceView()}${s.required===false?'<div class="wr22-actions"><button class="quiet" data-skip="compliance">Not applicable / continue →</button></div>':''}</div>`;case'putaway':return `<div class="wr22-task"><h3>Put away</h3>${putawayView()}<div class="wr22-actions"><button class="quiet" data-skip="putaway">Skip for now →</button></div></div>`;case'complete':return `<div class="wr22-task"><h3>Review & complete</h3><div class="wr22-card"><p>${missing().length?`Still needs attention · ${esc(missing().join(' · '))}`:'✓ Ready to complete'}</p></div><div class="wr22-actions"><button class="primary" data-complete>Complete WR</button></div></div>`;case'notify_customer':return `<div class="wr22-task"><h3>Notify customer</h3><div class="wr22-actions"><button class="primary" data-share>Share WR</button><button data-notified>Mark notified</button><button class="quiet" data-skip="notify_customer">Skip →</button></div></div>`;default:return `<div class="wr22-task"><h3>${esc(s.label)}</h3><div class="wr22-actions"><button class="primary" data-generic="${s.key}">Mark complete</button></div></div>`}}
const TABS=[['overview','Overview'],['parties','Parties'],['arrival','Arrival'],['cargo','Cargo'],['documents','Documents'],['compliance','Compliance'],['exceptions','Exceptions'],['activity','Activity']];
function record(){return `<nav class="wr22-tabs">${TABS.map(([k,l])=>`<button data-tab="${k}" class="${tab===k?'active':''}">${l}</button>`).join('')}</nav><section class="wr22-panel">${recordTab()}</section>`}
function recordTab(){return tab==='overview'?overview():tab==='parties'?partiesView():tab==='arrival'?arrivalView():tab==='cargo'?cargoView():tab==='documents'?documentsView():tab==='compliance'?complianceView():tab==='exceptions'?exceptionsView():activityView()}
function overview(){return `<div class="wr22-recordgrid"><div class="wr22-card"><h3>Warehouse Receipt</h3><div class="wr22-fields"><label class="wr22-field"><span>WR number</span><input value="${esc(S.wr.receipt_number)}" readonly></label><label class="wr22-field"><span>Status</span><input value="${esc(S.wr.status)}" readonly></label><label class="wr22-field"><span>Created</span><input value="${esc(fmt(S.wr.created_at))}" readonly></label><label class="wr22-field"><span>Received</span><input value="${esc(fmt(S.wr.received_at))}" readonly></label></div><div class="wr22-partygrid" style="margin-top:12px">${partyCard('customer')}${partyCard('shipper')}${partyCard('consignee')}</div></div><div class="wr22-card"><h3>Readiness</h3><p>${missing().length?'Items still need attention before final completion.':'No blocking items detected.'}</p>${missing().map(x=>`<span class="wr22-badge warn" style="margin:4px">${esc(x)}</span>`).join('')||'<span class="wr22-badge good">Ready</span>'}<div class="wr22-actions"><button data-workflow>Edit workflow</button></div></div></div>`}
function partiesView(){return `<div class="wr22-between"><div><h2 style="margin:0">Parties</h2><p style="color:#8194a8">Customer, Shipper and Consignee are the basic WR parties.</p></div><button class="wr22-btn" data-edit-parties>✎ Edit</button></div><div class="wr22-partygrid" style="margin-top:13px">${partyCard('customer')}${partyCard('shipper')}${partyCard('consignee')}</div>`}
function arrivalView(){const v=S.visit||{};return `<div class="wr22-card"><div class="wr22-between"><h3>Dock visit</h3><button class="wr22-btn" data-edit-arrival>✎ Edit</button></div>${timeline()}<div class="wr22-fields"><label class="wr22-field"><span>Carrier</span><input value="${esc(v.carrier_name_snapshot||'')}" readonly></label><label class="wr22-field"><span>Driver</span><input value="${esc(v.driver_name||'')}" readonly></label><label class="wr22-field"><span>BOL</span><input value="${esc(v.bol_number||'')}" readonly></label><label class="wr22-field"><span>PRO / tracking</span><input value="${esc(v.pro_number||v.tracking_number||'')}" readonly></label><label class="wr22-field"><span>Door</span><input value="${esc(v.door||'')}" readonly></label><label class="wr22-field"><span>Seal / trailer</span><input value="${esc([v.seal_number,v.trailer_number].filter(Boolean).join(' / '))}" readonly></label></div></div>`}
function flatCargo(){const out=[];const walk=(x,d=0)=>{out.push([x,d]);children(x.id).forEach(c=>walk(c,d+1))};roots().forEach(x=>walk(x));return out}
function cargoView(){const q=cargoQuery.trim().toLowerCase(),rows=flatCargo().filter(([x])=>!q||[x.handling_unit_code,x.package_type,x.description,x.sku,x.part_number,x.lot_number,x.serial_number].some(v=>String(v||'').toLowerCase().includes(q)));return `<div class="wr22-bar"><div><h3 style="margin:0">Physical cargo</h3><p style="margin:4px 0;color:#7f92a8;font-size:10px">Hierarchy stays visible. Drafts autosave.</p></div><div style="display:flex;gap:7px;flex-wrap:wrap"><input class="wr22-search" id="cargo-q" value="${esc(cargoQuery)}" placeholder="Search cargo, SKU, part…"><button class="wr22-btn primary" data-add-cargo>＋ Cargo</button></div></div>${rows.length?`<div class="wr22-bulk"><label><input type="checkbox" class="wr22-check" data-cargo-all> Select all</label><button class="danger" data-delete-selected ${selectedCargo.size?'':'disabled'}>Delete selected${selectedCargo.size?` (${selectedCargo.size})`:''}</button></div><div class="wr22-tablewrap"><table class="wr22-table"><thead><tr><th></th><th>Cargo</th><th>Description / part</th><th>Qty</th><th>Weight</th><th>Dimensions</th><th>Location</th><th>Controls</th><th>Actions</th></tr></thead><tbody>${rows.map(([x,d])=>cargoRow(x,d)).join('')}</tbody></table></div>`:'<div class="wr22-empty">No cargo recorded yet. Add the outer handling unit first.</div>'}`}
function cargoRow(x,d){const loc=S.locations.find(l=>l.id===(x.current_location_id||x.warehouse_location_id)),photos=S.docs.filter(z=>z.cargo_unit_id===x.id&&['PHOTO','DAMAGE_PHOTO','DG_LABEL'].includes(String(z.category||'').toUpperCase())).length,controls=S.controls.filter(z=>z.cargo_unit_id===x.id).map(z=>z.control_type).join(' · '),dims=x.length_in&&x.width_in&&x.height_in?`${Number(x.length_in).toFixed(1)}×${Number(x.width_in).toFixed(1)}×${Number(x.height_in).toFixed(1)} in`:'—';return `<tr><td><input class="wr22-check" type="checkbox" data-cargo-select="${x.id}" ${selectedCargo.has(x.id)?'checked':''}></td><td><span class="wr22-indent ${d?'child':''}">${d?'↳':'▾'} ${esc(x.handling_unit_code||'')} ${esc(x.package_type||'')}</span>${x.metadata?.editor_draft?' <span class="wr22-badge warn">draft</span>':''}</td><td><b>${esc(x.description||'—')}</b><br><small>${esc(x.part_number||x.sku||'')}</small></td><td>${esc(x.quantity||0)} ${esc(x.uom||'')}</td><td>${x.weight_lb?`${Number(x.weight_lb).toFixed(1)} lb`:'—'}</td><td>${dims}</td><td>${esc(loc?.code||'—')}</td><td>${controls?`<span class="wr22-badge warn">${esc(controls)}</span>`:''}${photos?` <span class="wr22-badge">📷 ${photos}</span>`:''}</td><td><div class="wr22-rowactions"><button data-edit-cargo="${x.id}">Edit</button><button data-inside="${x.id}">+ Inside</button><button data-photo="${x.id}">Photo</button><button data-control="${x.id}">DG / Customs</button><button data-exception="${x.id}">Exception</button><button data-label="${x.id}">Label</button><button class="wr22-danger" data-delete-cargo="${x.id}">Delete</button></div></td></tr>`}
function documentsView(){const groups={};for(const d of S.docs){const key=docGroup==='cargo'?(d.cargo_unit_id?S.cargo.find(x=>x.id===d.cargo_unit_id)?.handling_unit_code||S.cargo.find(x=>x.id===d.cargo_unit_id)?.package_type||'Cargo':'Receipt-level'):(d.category||d.document_type||'Other');(groups[key] ||= []).push(d)}return `<div class="wr22-bar"><div><h3 style="margin:0">Documents</h3><p style="margin:4px 0;color:#7f92a8;font-size:10px">Organize by document type or cargo association.</p></div><div style="display:flex;gap:7px;flex-wrap:wrap"><select id="doc-group" class="wr22-search"><option value="category" ${docGroup==='category'?'selected':''}>By category</option><option value="cargo" ${docGroup==='cargo'?'selected':''}>By cargo</option></select><button class="wr22-btn" data-doc-scan>Scan</button><button class="wr22-btn primary" data-doc-upload>Upload</button></div></div>${S.docs.length?`<div class="wr22-bulk"><label><input type="checkbox" class="wr22-check" data-doc-all> Select all</label><button data-download-selected ${selectedDocs.size?'':'disabled'}>Download selected${selectedDocs.size?` (${selectedDocs.size})`:''}</button><button data-share-selected ${selectedDocs.size?'':'disabled'}>Share selected</button><button data-download-all>Download all</button></div>`:''}<div class="wr22-docgroups">${Object.entries(groups).map(([k,ds])=>`<section class="wr22-docgroup"><h4>${esc(k)} · ${ds.length}</h4>${ds.map(docRow).join('')}</section>`).join('')||'<div class="wr22-empty">No documents yet.</div>'}</div>`}
function docRow(d){return `<div class="wr22-docrow"><input type="checkbox" class="wr22-check" data-doc-select="${d.id}" ${selectedDocs.has(d.id)?'checked':''}><div class="wr22-docicon">▤</div><div><b>${esc(d.display_name||d.file_name||d.document_type||'Document')}</b><small>${esc(d.category||d.document_type||'OTHER')} · ${fmt(d.created_at)}${d.extraction?' · OCR data available':''}</small></div><div class="wr22-docactions"><button data-doc-preview="${d.id}">Preview</button><button data-doc-download="${d.id}">Download</button><button data-doc-share="${d.id}">Share</button><button data-doc-tag="${d.id}">Tag</button></div></div>`}
function complianceView(){return `<div class="wr22-between"><div><h2 style="margin:0">Compliance controls</h2><p style="color:#8093a8">Structured DG, 7512 and FTZ state.</p></div><button class="wr22-btn" data-control-add>＋ Add control</button></div><div class="wr22-controlgrid" style="margin-top:13px">${['DG','IN_BOND_7512','FTZ'].map(t=>{const a=S.controls.filter(x=>x.control_type===t);return `<div class="wr22-control"><div class="wr22-k">${a.length?(a.every(x=>x.verified)?'VERIFIED':'PENDING'):'NOT APPLICABLE'}</div><h4>${t==='IN_BOND_7512'?'In-bond / 7512':t}</h4><p>${a.length?`${a.length} control${a.length===1?'':'s'} · ${a.filter(x=>x.verified).length} verified`:'No active control.'}</p></div>`}).join('')}</div>`}
function exceptionsView(){return `<div class="wr22-between"><div><h2 style="margin:0">Exception ledger</h2><p style="color:#8093a8">Operational exceptions remain open until resolved.</p></div><button class="wr22-btn" data-exception-add>＋ Exception</button></div><div class="wr22-docgroups">${S.flags.map(f=>`<div class="wr22-docgroup"><div class="wr22-between"><div><span class="wr22-badge warn">${esc(f.flag_type)}</span><h4>${esc(f.notes||'No notes')}</h4><small>${fmt(f.created_at)} · ${esc(f.severity||'')}</small></div><button class="wr22-btn" data-clear-flag="${f.id}">Resolve</button></div></div>`).join('')||'<div class="wr22-empty">No active exceptions.</div>'}</div>`}
function activityView(){return `<div class="wr22-docgroups">${S.events.slice().reverse().map(e=>`<div class="wr22-docgroup"><b>${esc(e.event_type)}</b><small style="display:block;color:#71869d;margin-top:4px">${fmt(e.created_at)}</small></div>`).join('')||'<div class="wr22-empty">No workflow activity yet.</div>'}</div>`}
function putawayView(){return roots().filter(x=>!x.metadata?.editor_draft).map(x=>`<div class="wr22-card" style="margin-top:9px"><div class="wr22-between"><div><b>${esc(x.handling_unit_code||x.package_type)}</b><div style="color:#71869d;font-size:9px">${esc(x.description||'')}</div></div><button class="wr22-btn" data-putaway="${x.id}">${x.current_location_id||x.warehouse_location_id?'Change location':'Assign location'}</button></div></div>`).join('')||'<div class="wr22-empty">Add cargo before put-away.</div>'}
function render(){document.body.classList.add('wr22-active');document.body.classList.remove('wr19-active','wr21-active');main.innerHTML=`<section class="wr22">${head()}${mode==='guided'?guided():record()}<input type="file" id="wr22-upload" hidden multiple></section>`;ensureBack();bind()}
function ensureBack(){let b=document.querySelector('.wr22-back');if(!b){b=document.createElement('button');b.className='wr22-back';b.textContent='‹ Receipts';b.onclick=()=>{document.body.classList.remove('wr22-active');b.remove();window.nodaraSetActive?.('wr');document.querySelector('[data-go="wr"],[data-route="wr"],[data-view="wr"]')?.click()||history.back()};document.body.appendChild(b)}}
function modal(html){const back=document.createElement('div'),box=document.createElement('div');back.className='wr22-modalback';box.className='wr22-modal';box.innerHTML=html;document.body.append(back,box);const close=()=>{back.remove();box.remove()};back.onclick=close;box.querySelector('[data-x]')?.addEventListener('click',close);return{box,close}}
function preview(inp,e){const p=inp.closest('[data-smart-wrap]')?.querySelector('[data-preview]');if(!p)return;if(!e){p.hidden=true;return}const a=S.addresses.find(x=>x.entity_id===e.id&&x.is_primary)||S.addresses.find(x=>x.entity_id===e.id),c=S.contacts.find(x=>x.entity_id===e.id&&x.is_primary)||S.contacts.find(x=>x.entity_id===e.id);p.innerHTML=`${esc([a?.line1,[a?.city,a?.state_region,a?.postal_code].filter(Boolean).join(' ')].filter(Boolean).join(' · ')||'No saved address')}${c?`<br>${esc([c.name,c.phone,c.email].filter(Boolean).join(' · '))}`:''}`;p.hidden=false}
function bindSmart(){main.querySelectorAll('[data-smart]').forEach(inp=>{const menu=inp.parentElement.querySelector('.wr22-smartmenu');const show=()=>{const q=inp.value.trim().toLowerCase(),rows=S.entities.filter(e=>!q||e.name.toLowerCase().includes(q)||String(e.code||'').toLowerCase().includes(q)).slice(0,7);menu.innerHTML=rows.map(e=>{const a=S.addresses.find(x=>x.entity_id===e.id&&x.is_primary)||S.addresses.find(x=>x.entity_id===e.id);return `<button data-pick="${e.id}"><b>${esc(e.name)}</b><small>${esc([a?.line1,a?.city,a?.state_region].filter(Boolean).join(' · ')||e.code||'Saved record')}</small></button>`}).join('')+`<button data-use-once>Use typed value for this WR only</button><button data-new-entity>＋ Create new master record</button>`;menu.hidden=false;menu.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{const e=ent(b.dataset.pick);inp.value=e.name;inp.dataset.entityId=e.id;preview(inp,e);menu.hidden=true});menu.querySelector('[data-use-once]')?.addEventListener('click',()=>{delete inp.dataset.entityId;menu.hidden=true});menu.querySelector('[data-new-entity]')?.addEventListener('click',()=>{menu.hidden=true;entityModal(inp.dataset.smart,inp.value,e=>{inp.value=e.name;inp.dataset.entityId=e.id;preview(inp,e)})})};inp.addEventListener('input',()=>{delete inp.dataset.entityId;preview(inp,null);show()});inp.addEventListener('focus',show);inp.addEventListener('blur',()=>setTimeout(()=>menu.hidden=true,180))})}
function entityModal(role,name,cb){const m=modal(`<div class="wr22-modalhead"><h3>New ${esc(role)} record</h3><button class="wr22-x" data-x>×</button></div><div class="wr22-fields"><label class="wr22-field"><span>Name</span><input id="e-name" value="${esc(name||'')}"></label><label class="wr22-field"><span>Address</span><input id="e-address"></label><label class="wr22-field"><span>City</span><input id="e-city"></label><label class="wr22-field"><span>State</span><input id="e-state"></label><label class="wr22-field"><span>Contact</span><input id="e-contact"></label><label class="wr22-field"><span>Email</span><input id="e-email"></label><label class="wr22-field"><span>Phone</span><input id="e-phone"></label></div><div class="wr22-actions"><button class="primary" id="e-save">Create & select</button></div>`);m.box.querySelector('#e-save').onclick=async()=>{const n=m.box.querySelector('#e-name').value.trim();if(!n)return;const{data:e,error}=await supabase.from('entities').insert({organization_id:S.wr.organization_id,name:n,roles:[String(role||'PARTY').toUpperCase()],email:m.box.querySelector('#e-email').value.trim()||null,phone:m.box.querySelector('#e-phone').value.trim()||null}).select().single();if(error)return alert(error.message);const line=m.box.querySelector('#e-address').value.trim();if(line)await supabase.from('entity_addresses').insert({organization_id:S.wr.organization_id,entity_id:e.id,address_type:'MAIN',line1:line,city:m.box.querySelector('#e-city').value.trim()||null,state_region:m.box.querySelector('#e-state').value.trim()||null,is_primary:true,active:true});const cn=m.box.querySelector('#e-contact').value.trim();if(cn)await supabase.from('entity_contacts').insert({organization_id:S.wr.organization_id,entity_id:e.id,name:cn,email:m.box.querySelector('#e-email').value.trim()||null,phone:m.box.querySelector('#e-phone').value.trim()||null,is_primary:true,active:true});await load(wrId);cb(ent(e.id)||e);m.close()}}
async function ensureDraft(x,parent){if(x)return x;const t=parent?'BOX':'PALLET',u=packageTypes().find(z=>z[0]===t)?.[1]||t,{data,error}=await supabase.from('cargo_units').insert({organization_id:S.wr.organization_id,job_id:S.wr.job_id,parent_id:parent?.id||null,package_type:t,quantity:1,uom:u,status:'received',processing_status:'pending',metadata:{editor_draft:true}}).select().single();if(error){alert(error.message);return null}S.cargo.push(data);return data}
async function cargoModal(existing=null,parent=null){let x=await ensureDraft(existing,parent);if(!x)return;let inventoryItemId=x.inventory_item_id||null,timer=null;const weightUnit=x.metadata?.input_weight_unit||S.units?.weight_unit||'LB',dimUnit=x.metadata?.input_dimension_unit||S.units?.dimension_unit||'IN',dw=x.weight_lb==null?'':(weightUnit==='KG'?Number(x.weight_lb)/2.2046226218:Number(x.weight_lb)),dd=n=>n==null?'':(dimUnit==='CM'?Number(n)*2.54:Number(n));const sib=S.cargo.filter(z=>z.parent_id===x.parent_id),par=x.parent_id?S.cargo.find(z=>z.id===x.parent_id):null;const m=modal(`<div class="wr22-modalhead"><div><div class="wr22-k">CARGO · AUTOSAVE</div><h3>${esc(x.handling_unit_code||x.package_type||'Cargo')}</h3></div><button class="wr22-x" data-x>×</button></div><div class="wr22-cargonav">${par?`<button data-nav="${par.id}">← ${esc(par.handling_unit_code||par.package_type)}</button>`:''}${sib.map(z=>`<button data-nav="${z.id}" class="${z.id===x.id?'active':''}">${esc(z.handling_unit_code||z.package_type)}</button>`).join('')}<button data-inside-editor>＋ Inside</button></div><div class="wr22-compact"><div class="wr22-pill"><input id="c-qty" type="number" value="${esc(x.quantity||1)}"></div><label class="wr22-field"><span>Package type</span><select id="c-type">${packageTypes().map(([t])=>`<option ${t===x.package_type?'selected':''}>${t}</option>`).join('')}<option value="__NEW__">＋ Add type…</option></select></label><label class="wr22-field" style="position:relative"><span>Description / part / SKU</span><input id="c-desc" value="${esc(x.description||'')}" placeholder="Describe or search item master"><div class="wr22-itemmenu" hidden></div></label></div><div class="wr22-fields"><label class="wr22-field"><span>Gross weight</span><div class="wr22-pill"><input id="c-weight" type="number" step="any" value="${esc(dw)}"><select id="c-wu"><option ${weightUnit==='LB'?'selected':''}>LB</option><option ${weightUnit==='KG'?'selected':''}>KG</option></select></div></label><label class="wr22-field"><span>Dimensions</span><div class="wr22-pill"><input id="c-l" type="number" placeholder="L" value="${esc(dd(x.length_in))}"><input id="c-w" type="number" placeholder="W" value="${esc(dd(x.width_in))}"><input id="c-h" type="number" placeholder="H" value="${esc(dd(x.height_in))}"><select id="c-du"><option ${dimUnit==='IN'?'selected':''}>IN</option><option ${dimUnit==='CM'?'selected':''}>CM</option></select></div></label></div><details class="wr22-details"><summary>Part / inventory details</summary><div class="wr22-fields"><label class="wr22-field" style="position:relative"><span>Part number</span><input id="c-part" value="${esc(x.part_number||'')}" placeholder="Search saved part"><div class="wr22-itemmenu" hidden></div></label><label class="wr22-field"><span>SKU</span><input id="c-sku" value="${esc(x.sku||'')}"></label><label class="wr22-field"><span>Lot</span><input id="c-lot" value="${esc(x.lot_number||'')}"></label><label class="wr22-field"><span>Serial</span><input id="c-serial" value="${esc(x.serial_number||'')}"></label></div></details><div class="wr22-metrics"><div class="wr22-metric"><small>UOM</small><b id="c-uom">${esc(x.uom||'—')}</b></div><div class="wr22-metric"><small>Volume</small><b id="c-vol">—</b></div><div class="wr22-metric"><small>Chargeable</small><b id="c-chg">—</b></div></div><div class="wr22-draftstate" id="c-state">Autosaved draft</div><div class="wr22-actions"><button class="wr22-icon" id="c-photo">${cameraIcon} Photo</button><button id="c-control">DG / Customs</button><button id="c-exception">Exception</button><button class="wr22-danger" id="c-delete">Delete</button><button class="primary" id="c-done">Done</button></div>`);const q=s=>m.box.querySelector(s),num=s=>q(s).value===''?null:Number(q(s).value),type=q('#c-type');const calc=()=>{let l=num('#c-l'),w=num('#c-w'),h=num('#c-h');if(q('#c-du').value==='CM'){l=l/2.54;w=w/2.54;h=h/2.54}q('#c-uom').textContent=packageTypes().find(z=>z[0]===type.value)?.[1]||type.value;q('#c-vol').textContent=l&&w&&h?(l*w*h*0.000016387064).toFixed(3)+' m³':'—';q('#c-chg').textContent=l&&w&&h?(l*w*h/166).toFixed(1)+' lb':'—'};const payload=()=>{let wt=num('#c-weight');if(wt!=null&&q('#c-wu').value==='KG')wt*=2.2046226218;let l=num('#c-l'),w=num('#c-w'),h=num('#c-h');if(q('#c-du').value==='CM'){l=l==null?null:l/2.54;w=w==null?null:w/2.54;h=h==null?null:h/2.54}return{package_type:type.value,quantity:num('#c-qty')||1,uom:packageTypes().find(z=>z[0]===type.value)?.[1]||type.value,description:q('#c-desc').value.trim()||null,inventory_item_id:inventoryItemId,part_number:q('#c-part').value.trim()||null,sku:q('#c-sku').value.trim()||null,lot_number:q('#c-lot').value.trim()||null,serial_number:q('#c-serial').value.trim()||null,weight_lb:wt,length_in:l,width_in:w,height_in:h,metadata:{...(x.metadata||{}),editor_draft:true,input_weight_unit:q('#c-wu').value,input_dimension_unit:q('#c-du').value}}};const save=()=>{clearTimeout(timer);q('#c-state').textContent='Saving…';timer=setTimeout(async()=>{const p=payload(),{error}=await supabase.from('cargo_units').update(p).eq('id',x.id);if(!error)Object.assign(x,p);q('#c-state').textContent=error?'Save failed':'Saved';calc()},300)};m.box.querySelectorAll('input,select').forEach(e=>{e.addEventListener('input',save);e.addEventListener('change',save)});type.onchange=()=>type.value==='__NEW__'?packageTypeModal(o=>{const op=document.createElement('option');op.value=o.code;op.textContent=o.label;type.insertBefore(op,type.lastElementChild);type.value=o.code;save()}):save();calc();
 const itemSearch=inp=>{const menu=inp.parentElement.querySelector('.wr22-itemmenu');const show=()=>{const val=inp.value.trim().toLowerCase(),owner=S.job?.customer_id,items=S.items.filter(i=>(!owner||!i.owner_entity_id||i.owner_entity_id===owner)&&(!val||[i.part_number,i.sku,i.description,i.metadata?.barcode].some(v=>String(v||'').toLowerCase().includes(val)))).slice(0,7);menu.innerHTML=items.map(i=>`<button data-item="${i.id}"><b>${esc(i.part_number||i.sku||'Item')}</b><small>${esc([i.sku,i.description].filter(Boolean).join(' · '))}</small></button>`).join('')+'<button data-item-new>＋ Create new part master</button>';menu.hidden=false;menu.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{const i=S.items.find(z=>z.id===b.dataset.item);inventoryItemId=i.id;q('#c-part').value=i.part_number||'';q('#c-sku').value=i.sku||'';q('#c-desc').value=i.description||q('#c-desc').value;const md=i.metadata||{};if(md.weight_lb!=null){q('#c-wu').value='LB';q('#c-weight').value=md.weight_lb}if(md.length_in!=null){q('#c-du').value='IN';q('#c-l').value=md.length_in;q('#c-w').value=md.width_in??'';q('#c-h').value=md.height_in??''}menu.hidden=true;save();calc()});menu.querySelector('[data-item-new]')?.addEventListener('click',()=>{menu.hidden=true;itemModal(inp.value,i=>{inventoryItemId=i.id;q('#c-part').value=i.part_number||'';q('#c-sku').value=i.sku||'';q('#c-desc').value=i.description||q('#c-desc').value;save()})})};inp.addEventListener('input',show);inp.addEventListener('focus',show);inp.addEventListener('blur',()=>setTimeout(()=>menu.hidden=true,180))};itemSearch(q('#c-part'));itemSearch(q('#c-desc'));
 m.box.querySelectorAll('[data-nav]').forEach(b=>b.onclick=async()=>{await supabase.from('cargo_units').update(payload()).eq('id',x.id);m.close();await load(wrId);cargoModal(S.cargo.find(z=>z.id===b.dataset.nav))});q('[data-inside-editor]').onclick=async()=>{await supabase.from('cargo_units').update(payload()).eq('id',x.id);m.close();await load(wrId);cargoModal(null,S.cargo.find(z=>z.id===x.id))};q('#c-photo').onclick=async()=>{await supabase.from('cargo_units').update(payload()).eq('id',x.id);window.NodaraWRMedia?.openCargoCamera?.({cargoId:x.id})};q('#c-control').onclick=async()=>{await supabase.from('cargo_units').update(payload()).eq('id',x.id);controlModal(x.id)};q('#c-exception').onclick=async()=>{await supabase.from('cargo_units').update(payload()).eq('id',x.id);exceptionModal(x.id)};q('#c-delete').onclick=async()=>{if(confirm('Delete this cargo and nested cargo?')){m.close();await deleteCargo([x.id])}};q('#c-done').onclick=async()=>{clearTimeout(timer);const p=payload();p.processing_status='processed';p.status='received';p.metadata={...p.metadata,editor_draft:false};const{error}=await supabase.from('cargo_units').update(p).eq('id',x.id);if(error)return alert(error.message);m.close();manualStep=null;await rerender(true);toast('Cargo saved ✓')}}
function itemModal(seed,cb){if(!S.job?.customer_id)return alert('Select the customer first to create a reusable Part Master record. You can still type a part/SKU for this WR only.');const m=modal(`<div class="wr22-modalhead"><h3>New part master</h3><button class="wr22-x" data-x>×</button></div><div class="wr22-fields"><label class="wr22-field"><span>Part number</span><input id="i-part" value="${esc(seed||'')}"></label><label class="wr22-field"><span>SKU</span><input id="i-sku"></label><label class="wr22-field"><span>Description</span><input id="i-desc"></label><label class="wr22-field"><span>Base UOM</span><input id="i-uom" value="EA"></label></div><div class="wr22-actions"><button class="primary" id="i-save">Create & use</button></div>`);m.box.querySelector('#i-save').onclick=async()=>{const part=m.box.querySelector('#i-part').value.trim();if(!part)return;const{data,error}=await supabase.from('inventory_items').insert({organization_id:S.wr.organization_id,owner_entity_id:S.job.customer_id,part_number:part,sku:m.box.querySelector('#i-sku').value.trim()||null,description:m.box.querySelector('#i-desc').value.trim()||null,base_uom:m.box.querySelector('#i-uom').value.trim()||'EA',metadata:{}}).select().single();if(error)return alert(error.message);S.items.push(data);cb(data);m.close()}}
function packageTypeModal(cb){const m=modal(`<div class="wr22-modalhead"><h3>New package type</h3><button class="wr22-x" data-x>×</button></div><div class="wr22-fields"><label class="wr22-field"><span>Name / code</span><input id="p-code"></label><label class="wr22-field"><span>Default UOM</span><input id="p-uom"></label></div><div class="wr22-actions"><button class="primary" id="p-save">Add type</button></div>`);m.box.querySelector('#p-save').onclick=async()=>{const code=m.box.querySelector('#p-code').value.trim().toUpperCase(),uom=m.box.querySelector('#p-uom').value.trim().toUpperCase();if(!code)return;const{data,error}=await supabase.from('organization_reference_options').insert({organization_id:S.wr.organization_id,option_group:'PACKAGE_TYPE',code,label:code,uom:uom||code,active:true}).select().single();if(error)return alert(error.message);S.options.push(data);cb(data);m.close()}}
function controlModal(cargoId=null){const m=modal(`<div class="wr22-modalhead"><h3>Compliance control</h3><button class="wr22-x" data-x>×</button></div><div class="wr22-fields"><label class="wr22-field"><span>Control</span><select id="ct-type"><option value="DG">Dangerous Goods</option><option value="IN_BOND_7512">In-bond / 7512</option><option value="FTZ">FTZ</option></select></label><label class="wr22-field"><span>Status</span><select id="ct-status"><option>pending</option><option>verified</option><option>hold</option><option>released</option></select></label><label class="wr22-field"><span>Reference / UN / bond</span><input id="ct-ref"></label><label class="wr22-field"><span>Class / detail</span><input id="ct-detail"></label></div><div class="wr22-actions"><button class="primary" id="ct-save">Add control</button></div>`);m.box.querySelector('#ct-save').onclick=async()=>{const st=m.box.querySelector('#ct-status').value,ok=['verified','released'].includes(st),{error}=await supabase.from('receiving_controls').insert({organization_id:S.wr.organization_id,warehouse_receipt_id:wrId,cargo_unit_id:cargoId,control_type:m.box.querySelector('#ct-type').value,status:st,verified:ok,verified_at:ok?new Date().toISOString():null,verified_by:ok?await uid():null,details:{reference:m.box.querySelector('#ct-ref').value.trim(),detail:m.box.querySelector('#ct-detail').value.trim()}});if(error)return alert(error.message);m.close();await rerender()}}
function exceptionModal(cargoId=null,preset='DAMAGE'){const m=modal(`<div class="wr22-modalhead"><h3>Add exception</h3><button class="wr22-x" data-x>×</button></div><div class="wr22-fields"><label class="wr22-field"><span>Type</span><select id="ex-type">${['DAMAGE','SHORTAGE','OVERAGE','WET','OPEN_PACKAGE','SEAL_DISCREPANCY','WRONG_CARGO','UNKNOWN_CARGO','MEASUREMENT_DISCREPANCY','HOLD','OTHER'].map(x=>`<option ${x===preset?'selected':''}>${x}</option>`).join('')}</select></label><label class="wr22-field"><span>Severity</span><select id="ex-sev"><option>info</option><option selected>warning</option><option>critical</option></select></label><label class="wr22-field" style="grid-column:1/-1"><span>Notes</span><textarea id="ex-notes"></textarea></label></div><div class="wr22-actions"><button class="primary" id="ex-save">Create exception</button></div>`);m.box.querySelector('#ex-save').onclick=async()=>{const{error}=await supabase.from('operational_flags').insert({organization_id:S.wr.organization_id,warehouse_receipt_id:wrId,cargo_unit_id:cargoId,flag_type:m.box.querySelector('#ex-type').value,severity:m.box.querySelector('#ex-sev').value,active:true,source:'USER',notes:m.box.querySelector('#ex-notes').value.trim()||null,created_by:await uid()});if(error)return alert(error.message);m.close();await rerender()}}
function putawayModal(id){const x=S.cargo.find(z=>z.id===id),m=modal(`<div class="wr22-modalhead"><h3>Put away ${esc(x?.handling_unit_code||x?.package_type||'cargo')}</h3><button class="wr22-x" data-x>×</button></div><div class="wr22-actions"><button class="wr22-icon" id="pa-scan">${scanIcon} Scan location</button></div><label class="wr22-field"><span>Location</span><select id="pa-loc">${S.locations.map(l=>`<option value="${l.id}">${esc(l.code)} · ${esc(l.name||'')}</option>`).join('')}</select></label><div class="wr22-actions"><button class="primary" id="pa-save">Assign location</button></div>`);m.box.querySelector('#pa-scan').onclick=()=>window.nodaraScanTask?.({title:'Scan destination location',onScan:async code=>{const l=S.locations.find(z=>z.code===code);if(!l)return false;m.box.querySelector('#pa-loc').value=l.id;return true}});m.box.querySelector('#pa-save').onclick=async()=>{const{error}=await supabase.from('cargo_units').update({current_location_id:m.box.querySelector('#pa-loc').value,warehouse_location_id:m.box.querySelector('#pa-loc').value}).eq('id',id);if(error)return alert(error.message);m.close();await rerender()}}
async function deleteCargo(ids){const{data:all}=await supabase.from('cargo_units').select('id,parent_id').eq('job_id',S.wr.job_id);const set=new Set(ids);let changed=true;while(changed){changed=false;for(const x of all||[])if(x.parent_id&&set.has(x.parent_id)&&!set.has(x.id)){set.add(x.id);changed=true}}const{error}=await supabase.from('cargo_units').delete().in('id',[...set]);if(error)return alert(error.message);selectedCargo.clear();await rerender();toast('Cargo deleted')}
function docMetaModal(kind='upload',docId=null){const tags=['BOL','PACKING_LIST','COMMERCIAL_INVOICE','7512','POD','DG_DOCUMENT','DRIVER_ID','PHOTO','OTHER',...(S.options||[]).filter(x=>x.option_group==='DOCUMENT_TAG'&&x.active).map(x=>x.code)];const uniq=[...new Set(tags)];const m=modal(`<div class="wr22-modalhead"><h3>${docId?'Tag document':kind==='scan'?'Scan document':'Upload document'}</h3><button class="wr22-x" data-x>×</button></div><div class="wr22-fields"><label class="wr22-field"><span>Document type</span><select id="d-tag">${uniq.map(t=>`<option>${esc(t)}</option>`).join('')}<option value="__NEW__">＋ Add tag…</option></select></label><label class="wr22-field"><span>Associate to cargo</span><select id="d-cargo"><option value="">Receipt-level</option>${flatCargo().map(([x,d])=>`<option value="${x.id}">${'— '.repeat(d)}${esc(x.handling_unit_code||x.package_type)}</option>`).join('')}</select></label></div><div class="wr22-actions"><button class="primary" id="d-go">${docId?'Apply tag':kind==='scan'?'Open scanner':'Choose file'}</button></div>`);const tag=m.box.querySelector('#d-tag');tag.onchange=()=>{if(tag.value!=='__NEW__')return;const val=prompt('New reusable document tag');if(!val){tag.value='OTHER';return}const code=val.trim().toUpperCase().replace(/\s+/g,'_');supabase.from('organization_reference_options').insert({organization_id:S.wr.organization_id,option_group:'DOCUMENT_TAG',code,label:val.trim(),active:true}).then(({data,error})=>{if(!error){S.options.push({option_group:'DOCUMENT_TAG',code,label:val.trim(),active:true});const o=document.createElement('option');o.value=code;o.textContent=val.trim();tag.insertBefore(o,tag.lastElementChild);tag.value=code}})};m.box.querySelector('#d-go').onclick=async()=>{const meta={category:tag.value,cargoId:m.box.querySelector('#d-cargo').value||null};if(docId){const{error}=await supabase.from('documents').update({category:meta.category,cargo_unit_id:meta.cargoId}).eq('id',docId);if(error)return alert(error.message);m.close();await rerender();return}if(kind==='scan'){m.close();window.NodaraWRScanner?.open?.({category:meta.category,kind:meta.category==='DRIVER_ID'?'DRIVER_ID':null});return}pendingDocMeta=meta;m.close();main.querySelector('#wr22-upload')?.click()}}
async function uploadFiles(e){const meta=pendingDocMeta||{category:'OTHER',cargoId:null};for(const f of e.target.files||[]){const{data:tx}=await supabase.from('transactions').select('id').eq('transaction_type','WAREHOUSE_RECEIPT').eq('domain_record_id',wrId).maybeSingle();if(!tx?.id)return alert('WR transaction is missing.');const path=`${S.wr.organization_id}/${tx.id}/transaction/${crypto.randomUUID()}_${f.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`,up=await supabase.storage.from('nodara-documents').upload(path,f,{contentType:f.type,upsert:false});if(up.error)return alert(up.error.message);const reg=await supabase.rpc('nodara_register_document',{p_transaction_id:tx.id,p_document_type:meta.category,p_storage_path:path,p_file_name:f.name,p_mime_type:f.type,p_cargo_object_id:null,p_entity_id:null,p_template_id:null,p_display_name:f.name,p_document_number:null,p_category:meta.category,p_link_role:'SUPPORTING',p_source:'USER',p_status:'ACTIVE',p_notes:null,p_metadata:{uploaded_from:'WR_V22'},p_provenance:{source_type:'USER',surface:'WR_V22'}});if(reg.error)return alert(reg.error.message)}pendingDocMeta=null;e.target.value='';await rerender()}
async function docAction(id,kind){const d=S.docs.find(x=>x.id===id);if(!d)return;const{data}=await supabase.storage.from('nodara-documents').createSignedUrl(d.storage_path,180);if(!data?.signedUrl)return alert('Could not open document.');if(kind==='share'&&navigator.share){try{await navigator.share({title:d.display_name||d.file_name,url:data.signedUrl})}catch{};return}window.open(data.signedUrl,'_blank')}
async function batchDocs(kind,all=false){const ids=all?S.docs.map(x=>x.id):[...selectedDocs];for(const id of ids){if(kind==='share'){await docAction(id,'share');break}await docAction(id,'download')}}
async function checkin(){const carrier=main.querySelector('#g-carrier'),payload={carrier_name_snapshot:carrier?.value.trim()||null,carrier_id:carrier?.dataset.entityId||null,driver_name:main.querySelector('#g-driver')?.value.trim()||null,door:main.querySelector('#g-door')?.value.trim()||null,bol_number:main.querySelector('#g-ref')?.value.trim()||null,time_in:S.visit?.time_in||new Date().toISOString()};let error;if(S.visit)({error}=await supabase.from('warehouse_visits').update(payload).eq('id',S.visit.id));else({error}=await supabase.from('warehouse_visits').insert({...payload,organization_id:S.wr.organization_id,warehouse_receipt_id:wrId,direction:'inbound',created_by:await uid()}));if(error)return alert(error.message);manualStep=null;await rerender(true);toast('Checked in ✓')}
async function visitUpdate(payload,msg){if(!S.visit)return alert('Check in first.');const{error}=await supabase.from('warehouse_visits').update(payload).eq('id',S.visit.id);if(error)return alert(error.message);manualStep=null;await rerender(true);toast(msg+' ✓')}
async function verify(){if(!main.querySelector('#g-verify')?.checked)return alert('Confirm the verification statement.');await visitUpdate({driver_id_verified:true,driver_id_verified_at:new Date().toISOString(),driver_id_verified_by:await uid()},'ID verified')}
async function finishUnload(){await visitUpdate({unload_expected_qty:Number(main.querySelector('#g-exp')?.value||0)||null,unload_actual_qty:Number(main.querySelector('#g-act')?.value||0)||null,unload_uom:main.querySelector('#g-uom')?.value||'PLT',operation_completed_at:new Date().toISOString()},'Unload finished')}
async function saveParties(){for(const[r,id]of[['customer','g-customer'],['shipper','g-shipper'],['consignee','g-consignee']]){const inp=main.querySelector('#'+id),name=inp?.value.trim();if(!name)continue;const e=inp.dataset.entityId?ent(inp.dataset.entityId):S.entities.find(x=>x.name.toLowerCase()===name.toLowerCase());if(r==='customer'){if(e)await supabase.from('jobs').update({customer_id:e.id}).eq('id',S.wr.job_id)}else{await supabase.from('warehouse_receipt_parties').delete().eq('warehouse_receipt_id',wrId).eq('role',r);const{error}=await supabase.from('warehouse_receipt_parties').insert({organization_id:S.wr.organization_id,warehouse_receipt_id:wrId,role:r,entity_id:e?.id||null,display_name:name,phone:e?.phone||null,email:e?.email||null});if(error)return alert(error.message)}}await supabase.from('warehouse_receipts').update({identification_status:'identified'}).eq('id',wrId);manualStep=null;await rerender(true);toast('Parties saved ✓')}
