export async function openNewReceivingV22(){document.body.classList.remove('wr19-active','wr21-active','wr22-active');document.querySelector('.wr22-back')?.remove();window.nodaraSetActive?.('wr');main.style.visibility='visible';main.innerHTML=`<section class="wr22-arrival"><div class="wr22-arrivalhero"><div class="wr22-k">WAREHOUSE RECEIVING</div><h1>New receiving</h1><p>Scan first. A provisional WR is created as soon as you begin capturing the arrival.</p></div><div class="wr22-arrivalgrid"><button class="wr22-arrivalaction" id="nr-code">${scanIcon}<b>Scan code / label</b><small>Barcode · QR · BOL · PRO · AWB · shipping label</small></button><button class="wr22-arrivalaction" id="nr-doc">${docIcon}<b>Scan document</b><small>Capture BOL or paperwork and run document intelligence</small></button></div><div class="wr22-startcard" style="margin-top:10px"><h3>Or start manually</h3><div class="wr22-fields"><label class="wr22-field"><span>Reference type</span><select id="nr-type"><option>BOL</option><option>PRO</option><option>TRACKING</option><option>AWB</option><option>PO</option></select></label><label class="wr22-field"><span>Reference</span><input id="nr-ref" placeholder="Type reference"></label></div><div class="wr22-actions"><button class="primary" id="nr-find">Find expected cargo</button><button id="nr-unidentified">Continue unidentified</button></div></div></section>`;const create=async ref=>{const type=main.querySelector('#nr-type')?.value||'BOL',typed=main.querySelector('#nr-ref')?.value.trim()||'',value=(ref??typed)||null,{data,error}=await supabase.rpc('create_warehouse_receipt_shell_v1',{p_reference_type:type,p_reference_value:value,p_expected_source_type:null,p_expected_source_id:null,p_expected_snapshot:{source:'WR_V22'}});if(error)return alert(error.message);await mountWarehouseReceiptV22(data.warehouse_receipt_id,{view:'guided'});return data.warehouse_receipt_id};main.querySelector('#nr-unidentified').onclick=()=>create(null);main.querySelector('#nr-find').onclick=async()=>{const ref=main.querySelector('#nr-ref').value.trim();if(!ref)return alert('Scan or enter a reference first.');const{data}=await supabase.from('shipment_references').select('warehouse_receipt_id,reference_value').eq('reference_value',ref).limit(2);if(data?.length===1&&data[0].warehouse_receipt_id)return mountWarehouseReceiptV22(data[0].warehouse_receipt_id,{view:'guided'});await create(ref)};main.querySelector('#nr-code').onclick=()=>window.nodaraScanTask?.({title:'Scan arrival',hint:'Barcode · QR · BOL · PRO · AWB · shipping label',onScan:async code=>{main.querySelector('#nr-ref').value=code;return true}});main.querySelector('#nr-doc').onclick=async()=>{const id=await create(null);if(id)setTimeout(()=>window.NodaraWRScanner?.open?.({category:'BOL'}),150)}}
